# Let me create a more systematic approach to find the pattern
inputs = ['whubf', 'vchggg', 'eywi', 'cuhawh', 'wcu']
outputs = ['ehubuy', 'dicchggg', 'eyei', 'cuhaeh', 'ecu']

# Check character-by-character differences
for i in range(len(inputs)):
    print(f"'{inputs[i]}' -> '{outputs[i]}'")
    if len(inputs[i]) == len(outputs[i]):
        for j in range(len(inputs[i])):
            if inputs[i][j] != outputs[i][j]:
                print(f"  Position {j}: '{inputs[i][j]}' -> '{outputs[i][j]}'")
    else:
        print(f"  Length changed: {len(inputs[i])} -> {len(outputs[i])}")
    print()

# Look for repeated patterns
print("Looking for common character substitutions...")
all_chars_in_input = set()
all_chars_in_output = set()

for inp in inputs:
    all_chars_in_input.update(inp)
for out in outputs:
    all_chars_in_output.update(out)

print(f"Characters in inputs: {sorted(all_chars_in_input)}")
print(f"Characters in outputs: {sorted(all_chars_in_output)}")

